{
  "name": "AgroVision AI",
  "description": "Une application PWA intelligente pour la détection des mauvaises herbes, l'identification des plantes et la collaboration communautaire agricole en Afrique.",
  "requestFramePermissions": [
    "camera",
    "microphone"
  ]
}

export type UserRole = 'ONG' | 'Agriculteur' | 'Ingénieur Agronome' | 'Particulier';

export interface User {
  id: string;
  name: string;
  role: UserRole;
  avatar: string;
}

export interface PlantResult {
  commonName: string;
  africanNames: string[];
  scientificName: string;
  isWeed: boolean;
  benefits: string[];
  drawbacks: string[];
  healthImpact: {
    advantages: string[];
    disadvantages: string[];
  };
  eradicationMethod: string;
  description: string;
}

export interface ChatMessage {
  id: string;
  senderId: string;
  senderName: string;
  senderRole: UserRole;
  text: string;
  timestamp: number;
  image?: string;
  isAI?: boolean;
}

export interface PrivateConversation {
  id: string;
  targetUser: User;
  lastMessage: string;
}

import { GoogleGenAI, Type, GenerateContentResponse } from "@google/genai";
import { PlantResult } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

export const identifyPlant = async (base64Image: string): Promise<PlantResult | null> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: 'image/jpeg',
              data: base64Image,
            },
          },
          {
            text: `Analyze this plant or weed. Return ONLY a JSON object with the following structure:
            {
              "commonName": "string",
              "africanNames": ["list of names used in various African regions/languages"],
              "scientificName": "string",
              "isWeed": boolean,
              "benefits": ["list of agricultural or ecological benefits"],
              "drawbacks": ["list of drawbacks"],
              "healthImpact": {
                "advantages": ["medicinal or health benefits"],
                "disadvantages": ["toxicity or health risks"]
              },
              "eradicationMethod": "Detailed explanation of how to effectively and ecologically remove it if it's a weed",
              "description": "Short general description"
            }`
          }
        ]
      },
      config: {
        responseMimeType: "application/json",
      }
    });

    const text = response.text || "{}";
    return JSON.parse(text) as PlantResult;
  } catch (error) {
    console.error("Gemini Error:", error);
    return null;
  }
};

export const chatWithAI = async (message: string, history: { role: 'user' | 'model', parts: { text: string }[] }[]) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        { role: 'user', parts: [{ text: "Tu es un expert agronome africain. Aide les agriculteurs à identifier les maladies des plantes et les mauvaises herbes." }] },
        ...history.map(h => ({ role: h.role, parts: h.parts })),
        { role: 'user', parts: [{ text: message }] }
      ]
    });
    return response.text;
  } catch (error) {
    console.error("AI Chat Error:", error);
    return "Désolé, j'ai rencontré une erreur technique.";
  }
};

import React, { useState, useEffect } from 'react';
import { User, UserRole } from './types';
import Onboarding from './components/Onboarding';
import Layout from './components/Layout';
import PlantScanner from './components/PlantScanner';
import CommunityChat from './components/CommunityChat';
import Inbox from './components/Inbox';
import AIChat from './components/AIChat';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [activeTab, setActiveTab] = useState<'scan' | 'community' | 'inbox' | 'ai'>('scan');

  const handleLogin = (name: string, role: UserRole) => {
    const newUser: User = {
      id: Math.random().toString(36).substr(2, 9),
      name,
      role,
      avatar: `https://picsum.photos/seed/${name}/200`,
    };
    setUser(newUser);
    // Persist session if needed
  };

  if (!user) {
    return <Onboarding onComplete={handleLogin} />;
  }

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col max-w-md mx-auto relative shadow-2xl border-x border-gray-200 overflow-hidden">
      <Layout 
        user={user} 
        activeTab={activeTab} 
        setActiveTab={setActiveTab}
      >
        {activeTab === 'scan' && <PlantScanner />}
        {activeTab === 'community' && <CommunityChat user={user} />}
        {activeTab === 'inbox' && <Inbox user={user} />}
        {activeTab === 'ai' && <AIChat user={user} />}
      </Layout>
    </div>
  );
};

export default App;

