export default Layout;

import React, { useState } from 'react';
import { UserRole } from '../types';

interface OnboardingProps {
  onComplete: (name: string, role: UserRole) => void;
}

const Onboarding: React.FC<OnboardingProps> = ({ onComplete }) => {
  const [name, setName] = useState('');
  const [role, setRole] = useState<UserRole | ''>('');

  const roles: UserRole[] = ['Agriculteur', 'Ingénieur Agronome', 'ONG', 'Particulier'];

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (name && role) {
      onComplete(name, role);
    }
  };

  return (
    <div className="min-h-screen bg-emerald-600 flex items-center justify-center p-6">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-md overflow-hidden">
        <div className="bg-emerald-500 p-8 text-center text-white">
          <i className="fa-solid fa-leaf text-5xl mb-4"></i>
          <h2 className="text-2xl font-bold">Bienvenue sur AgroVision</h2>
          <p className="text-emerald-100 mt-2">L'agriculture intelligente à portée de main</p>
        </div>

        <form onSubmit={handleSubmit} className="p-8 space-y-6">
          <div>
            <label className="block text-sm font-semibold text-gray-700 mb-2">Votre Nom</label>
            <input 
              type="text" 
              value={name}
              onChange={(e) => setName(e.target.value)}
              className="w-full px-4 py-3 rounded-xl border border-gray-200 focus:ring-2 focus:ring-emerald-500 focus:border-transparent outline-none transition-all"
              placeholder="Ex: Moussa Koné"
              required
            />
          </div>

          <div>
            <label className="block text-sm font-semibold text-gray-700 mb-2">Votre Profil</label>
            <div className="grid grid-cols-2 gap-3">
              {roles.map((r) => (
                <button
                  key={r}
                  type="button"
                  onClick={() => setRole(r)}
                  className={`py-3 px-2 text-xs font-bold rounded-xl border transition-all ${
                    role === r 
                    ? 'bg-emerald-500 text-white border-emerald-500 shadow-lg' 
                    : 'bg-white text-gray-600 border-gray-200 hover:border-emerald-300'
                  }`}
                >
                  {r}
                </button>
              ))}
            </div>
          </div>

          <button
            type="submit"
            disabled={!name || !role}
            className="w-full bg-emerald-600 text-white py-4 rounded-xl font-bold text-lg shadow-lg disabled:opacity-50 disabled:cursor-not-allowed hover:bg-emerald-700 transition-colors"
          >
            Commencer
          </button>
        </form>
      </div>
    </div>
  );
};

export default Onboarding;

import React, { useState, useRef } from 'react';
import { identifyPlant } from '../services/gemini';
import { PlantResult } from '../types';

const PlantScanner: React.FC = () => {
  const [loading, setLoading] = useState(false);
  const [image, setImage] = useState<string | null>(null);
  const [result, setResult] = useState<PlantResult | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64 = (reader.result as string).split(',')[1];
        setImage(reader.result as string);
        processImage(base64);
      };
      reader.readAsDataURL(file);
    }
  };

  const processImage = async (base64: string) => {
    setLoading(true);
    setResult(null);
    try {
      const res = await identifyPlant(base64);
      setResult(res);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const reset = () => {
    setImage(null);
    setResult(null);
  };

  return (
    <div className="p-4 space-y-6">
      {!image ? (
        <div className="flex flex-col items-center justify-center h-80 bg-white rounded-3xl border-2 border-dashed border-emerald-200 shadow-sm p-8 text-center">
          <div className="w-20 h-20 bg-emerald-50 rounded-full flex items-center justify-center mb-4">
            <i className="fa-solid fa-camera text-4xl text-emerald-500"></i>
          </div>
          <h2 className="text-xl font-bold text-gray-800">Scanner une plante</h2>
          <p className="text-gray-500 mt-2 text-sm">Prenez en photo une plante ou une mauvaise herbe pour l'analyser.</p>
          <button 
            onClick={() => fileInputRef.current?.click()}
            className="mt-6 bg-emerald-500 text-white px-8 py-3 rounded-full font-bold shadow-lg hover:bg-emerald-600 transition-all flex items-center gap-2"
          >
            Ouvrir la Caméra
          </button>
          <input 
            type="file" 
            accept="image/*" 
            capture="environment" 
            ref={fileInputRef} 
            className="hidden" 
            onChange={handleFileChange} 
          />
        </div>
      ) : (
        <div className="space-y-6 animate-in fade-in duration-500">
          <div className="relative group overflow-hidden rounded-3xl shadow-xl">
            <img src={image} alt="Target" className="w-full h-64 object-cover" />
            <button 
              onClick={reset}
              className="absolute top-4 right-4 bg-black/50 text-white w-10 h-10 rounded-full flex items-center justify-center backdrop-blur-sm"
            >
              <i className="fa-solid fa-xmark"></i>
            </button>
            {loading && (
              <div className="absolute inset-0 bg-emerald-900/40 flex flex-col items-center justify-center backdrop-blur-sm text-white">
                <div className="w-12 h-12 border-4 border-white/30 border-t-white rounded-full animate-spin mb-4"></div>
                <p className="font-bold tracking-widest text-sm">ANALYSE IA EN COURS...</p>
              </div>
            )}
          </div>

          {result && (
            <div className="space-y-4 pb-20">
              <div className="bg-white rounded-3xl p-6 shadow-sm border border-emerald-50">
                <div className="flex justify-between items-start mb-2">
                  <h3 className="text-2xl font-bold text-gray-900">{result.commonName}</h3>
                  {result.isWeed && (
                    <span className="bg-red-100 text-red-600 px-3 py-1 rounded-full text-xs font-bold uppercase tracking-wider">Mauvaise herbe</span>
                  )}
                </div>
                <p className="text-emerald-700 italic font-medium text-sm mb-4">{result.scientificName}</p>
                <p className="text-gray-600 text-sm leading-relaxed">{result.description}</p>
              </div>

              <Section title="Noms en Afrique" icon="fa-earth-africa">
                <div className="flex flex-wrap gap-2">
                  {result.africanNames.map((n, i) => (
                    <span key={i} className="bg-amber-50 text-amber-800 px-3 py-1 rounded-lg text-sm font-medium border border-amber-100">{n}</span>
                  ))}
                </div>
              </Section>

              <div className="grid grid-cols-2 gap-4">
                <div className="bg-white rounded-3xl p-5 shadow-sm border border-emerald-50">
                  <h4 className="font-bold text-emerald-800 text-sm mb-3 flex items-center gap-2">
                    <i className="fa-solid fa-plus-circle text-emerald-500"></i> Avantages
                  </h4>
                  <ul className="text-xs space-y-2 text-gray-600 list-disc pl-4">
                    {result.benefits.map((b, i) => <li key={i}>{b}</li>)}
                  </ul>
                </div>
                <div className="bg-white rounded-3xl p-5 shadow-sm border border-emerald-50">
                  <h4 className="font-bold text-red-800 text-sm mb-3 flex items-center gap-2">
                    <i className="fa-solid fa-minus-circle text-red-500"></i> Inconvénients
                  </h4>
                  <ul className="text-xs space-y-2 text-gray-600 list-disc pl-4">
                    {result.drawbacks.map((d, i) => <li key={i}>{d}</li>)}
                  </ul>
                </div>
              </div>

              <Section title="Impact Santé" icon="fa-heart-pulse">
                <div className="space-y-4">
                  <div>
                    <h5 className="text-xs font-bold text-emerald-700 mb-2 uppercase">Bienfaits médicinaux :</h5>
                    <p className="text-sm text-gray-600 leading-relaxed">{result.healthImpact.advantages.join(", ")}</p>
                  </div>
                  <div>
                    <h5 className="text-xs font-bold text-red-700 mb-2 uppercase">Risques sanitaires :</h5>
                    <p className="text-sm text-gray-600 leading-relaxed">{result.healthImpact.disadvantages.join(", ")}</p>
                  </div>
                </div>
              </Section>

              <Section title="Éradication Efficace" icon="fa-broom" color="bg-amber-500">
                <p className="text-sm text-gray-700 leading-relaxed italic">{result.eradicationMethod}</p>
              </Section>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

const Section: React.FC<{ title: string, icon: string, color?: string, children: React.ReactNode }> = ({ title, icon, color = 'bg-emerald-500', children }) => (
  <div className="bg-white rounded-3xl p-6 shadow-sm border border-emerald-50">
    <div className="flex items-center gap-3 mb-4">
      <div className={`w-8 h-8 ${color} rounded-lg flex items-center justify-center text-white`}>
        <i className={`fa-solid ${icon} text-sm`}></i>
      </div>
      <h4 className="font-bold text-gray-800">{title}</h4>
    </div>
    {children}
  </div>
);

export default PlantScanner;

import React, { useState, useEffect, useRef } from 'react';
import { User, ChatMessage } from '../types';

interface CommunityChatProps {
  user: User;
}

const CommunityChat: React.FC<CommunityChatProps> = ({ user }) => {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [inputText, setInputText] = useState('');
  const scrollRef = useRef<HTMLDivElement>(null);

  // Initial dummy messages
  useEffect(() => {
    setMessages([
      {
        id: '1',
        senderId: 'bot',
        senderName: 'Système',
        senderRole: 'Particulier',
        text: 'Bienvenue dans l\'espace communautaire AgroVision ! Ici nous partageons nos conseils agricoles.',
        timestamp: Date.now() - 3600000,
      },
      {
        id: '2',
        senderId: 'agro1',
        senderName: 'Dr. Keita',
        senderRole: 'Ingénieur Agronome',
        text: 'Bonjour à tous, j\'ai remarqué une recrudescence du Striga dans le Nord Mali. Utilisez-vous des cultures pièges ?',
        timestamp: Date.now() - 1800000,
      }
    ]);
  }, []);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const sendMessage = () => {
    if (!inputText.trim()) return;
    const newMessage: ChatMessage = {
      id: Math.random().toString(),
      senderId: user.id,
      senderName: user.name,
      senderRole: user.role,
      text: inputText,
      timestamp: Date.now()
    };
    setMessages([...messages, newMessage]);
    setInputText('');
  };

  return (
    <div className="flex flex-col h-full bg-slate-50">
      <div className="bg-white px-4 py-2 border-b border-gray-100 shadow-sm flex items-center justify-between">
        <div>
          <h2 className="font-bold text-gray-800">Fil Communautaire</h2>
          <p className="text-[10px] text-emerald-600 font-bold uppercase tracking-widest">Global • Afrique de l'Ouest</p>
        </div>
        <div className="flex -space-x-2">
          {[1,2,3].map(i => (
            <img key={i} src={`https://picsum.photos/seed/${i}/100`} className="w-6 h-6 rounded-full border-2 border-white" alt="Active" />
          ))}
          <div className="w-6 h-6 rounded-full bg-emerald-100 flex items-center justify-center text-[8px] font-bold text-emerald-700 border-2 border-white">+12</div>
        </div>
      </div>

      <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-4">
        {messages.map((m) => (
          <div key={m.id} className={`flex gap-3 ${m.senderId === user.id ? 'flex-row-reverse' : ''}`}>
            <img 
              src={`https://picsum.photos/seed/${m.senderName}/100`} 
              className="w-10 h-10 rounded-2xl shadow-sm self-end" 
              alt="Avatar" 
            />
            <div className={`max-w-[75%] ${m.senderId === user.id ? 'items-end' : 'items-start'} flex flex-col`}>
              <div className="flex items-center gap-2 mb-1 px-1">
                <span className="text-[10px] font-bold text-gray-400">{m.senderName}</span>
                <span className="text-[8px] px-1.5 py-0.5 bg-gray-100 text-gray-500 rounded uppercase font-bold">{m.senderRole}</span>
              </div>
              <div className={`p-4 rounded-3xl text-sm shadow-sm ${
                m.senderId === user.id 
                ? 'bg-emerald-600 text-white rounded-br-none' 
                : 'bg-white text-gray-800 rounded-bl-none border border-gray-100'
              }`}>
                {m.text}
              </div>
              <span className="text-[8px] text-gray-400 mt-1">{new Date(m.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
            </div>
          </div>
        ))}
      </div>

      <div className="p-4 bg-white border-t border-gray-100 flex items-center gap-3 shadow-[0_-4px_10px_rgba(0,0,0,0.02)]">
        <button className="text-gray-400 hover:text-emerald-500 transition-colors">
          <i className="fa-solid fa-plus-circle text-xl"></i>
        </button>
        <input 
          type="text" 
          value={inputText}
          onChange={(e) => setInputText(e.target.value)}
          onKeyPress={(e) => e.key === 'Enter' && sendMessage()}
          placeholder="Échanger avec la communauté..." 
          className="flex-1 bg-slate-100 border-none rounded-2xl px-4 py-3 text-sm focus:ring-2 focus:ring-emerald-500 outline-none"
        />
        <button 
          onClick={sendMessage}
          className="bg-emerald-600 text-white w-10 h-10 rounded-2xl flex items-center justify-center shadow-lg active:scale-95 transition-all"
        >
          <i className="fa-solid fa-paper-plane text-xs"></i>
        </button>
      </div>
    </div>
  );
};

export default CommunityChat;

import React, { useState, useRef, useEffect } from 'react';
import { User } from '../types';
import { chatWithAI } from '../services/gemini';

interface AIChatProps {
  user: User;
}

const AIChat: React.FC<AIChatProps> = ({ user }) => {
  const [messages, setMessages] = useState<{ text: string, isAI: boolean }[]>([
    { text: `Bonjour ${user.name}, je suis votre assistant agronome. Comment puis-je vous aider aujourd'hui ?`, isAI: true }
  ]);
  const [inputText, setInputText] = useState('');
  const [loading, setLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [messages]);

  const handleSend = async () => {
    if (!inputText.trim() || loading) return;

    const userMsg = inputText;
    setInputText('');
    setMessages(prev => [...prev, { text: userMsg, isAI: false }]);
    setLoading(true);

    const history = messages.map(m => ({
      role: m.isAI ? 'model' as const : 'user' as const,
      parts: [{ text: m.text }]
    }));

    const response = await chatWithAI(userMsg, history);
    setMessages(prev => [...prev, { text: response || "Erreur de connexion", isAI: true }]);
    setLoading(false);
  };

  return (
    <div className="flex flex-col h-full bg-[#fdfdfd]">
      <div className="bg-gradient-to-r from-emerald-600 to-teal-700 p-6 text-white shadow-lg">
        <div className="flex items-center gap-4">
          <div className="w-12 h-12 bg-white/20 rounded-2xl backdrop-blur-md flex items-center justify-center relative border border-white/30">
            <i className="fa-solid fa-robot text-2xl"></i>
            <div className="absolute -bottom-1 -right-1 w-4 h-4 bg-emerald-400 border-2 border-emerald-600 rounded-full"></div>
          </div>
          <div>
            <h2 className="font-bold text-xl leading-tight">Assistant AgroVision</h2>
            <div className="flex items-center gap-1.5 mt-0.5">
              <span className="w-1.5 h-1.5 bg-emerald-300 rounded-full animate-pulse"></span>
              <span className="text-[10px] text-emerald-100 uppercase tracking-widest font-bold">Expert IA Agronome</span>
            </div>
          </div>
        </div>
      </div>

      <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-6 pt-6">
        {messages.map((m, i) => (
          <div key={i} className={`flex ${m.isAI ? 'justify-start' : 'justify-end'}`}>
            <div className={`max-w-[85%] p-4 rounded-3xl shadow-sm relative ${
              m.isAI 
              ? 'bg-white text-gray-800 rounded-bl-none border border-emerald-100 shadow-emerald-900/5' 
              : 'bg-emerald-600 text-white rounded-br-none shadow-emerald-700/20'
            }`}>
              {m.isAI && <i className="fa-solid fa-microchip absolute -top-3 -left-3 bg-emerald-500 text-white w-6 h-6 rounded-lg flex items-center justify-center text-[10px] shadow-md border border-white"></i>}
              <p className="text-sm leading-relaxed whitespace-pre-line">{m.text}</p>
            </div>
          </div>
        ))}
        {loading && (
          <div className="flex justify-start">
            <div className="bg-white p-4 rounded-2xl border border-emerald-50 flex gap-2">
              <span className="w-2 h-2 bg-emerald-400 rounded-full animate-bounce"></span>
              <span className="w-2 h-2 bg-emerald-400 rounded-full animate-bounce delay-75"></span>
              <span className="w-2 h-2 bg-emerald-400 rounded-full animate-bounce delay-150"></span>
            </div>
          </div>
        )}
      </div>

      <div className="p-4 bg-white border-t border-gray-100 safe-area-bottom">
        <div className="flex items-center gap-2 bg-slate-50 rounded-2xl p-2 border border-slate-100">
          <input 
            type="text" 
            value={inputText}
            onChange={(e) => setInputText(e.target.value)}
            onKeyPress={(e) => e.key === 'Enter' && handleSend()}
            placeholder="Posez une question agronomique..." 
            className="flex-1 bg-transparent px-3 py-2 text-sm outline-none"
          />
          <button 
            onClick={handleSend}
            disabled={loading}
            className="bg-emerald-600 text-white w-10 h-10 rounded-xl flex items-center justify-center disabled:opacity-50 shadow-md active:scale-95 transition-all"
          >
            <i className="fa-solid fa-paper-plane text-xs"></i>
          </button>
        </div>
      </div>
    </div>
  );
};

