import React, { useState } from 'react';
import { UserRole } from '../types';

interface OnboardingProps {
  onComplete: (data: { name: string, email: string, phone: string, role: UserRole }) => void;
}

const Onboarding: React.FC<OnboardingProps> = ({ onComplete }) => {
  const [step, setStep] = useState(1);
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    role: '' as UserRole | ''
  });

  const roles: UserRole[] = ['Agriculteur', 'Ingénieur Agronome', 'ONG', 'Particulier'];

  const nextStep = () => setStep(step + 1);
  const prevStep = () => setStep(step - 1);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (formData.name && formData.email && formData.phone && formData.role) {
      onComplete(formData as any);
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-emerald-600 via-emerald-700 to-teal-800 flex items-center justify-center p-6">
      <div className="bg-white/95 backdrop-blur-xl rounded-[2.5rem] shadow-2xl w-full max-w-md overflow-hidden animate-in zoom-in duration-500">

        {/* Progress Bar */}
        <div className="h-1.5 w-full bg-gray-100 flex">
          <div className={`h-full bg-emerald-500 transition-all duration-500 ${step === 1 ? 'w-1/2' : 'w-full'}`}></div>
        </div>

        <div className="p-8 text-center pt-10">
          <div className="w-20 h-20 bg-emerald-50 rounded-3xl flex items-center justify-center mx-auto mb-6 shadow-inner rotate-3">
            <i className="fa-solid fa-wheat-awn text-4xl text-emerald-600"></i>
          </div>
          <h2 className="text-3xl font-black text-gray-900 leading-tight">AgroVision AI</h2>
          <p className="text-gray-500 mt-2 font-medium">Rejoignez la révolution agricole africaine</p>
        </div>

        <form onSubmit={handleSubmit} className="p-8 pt-2 space-y-5">
          {step === 1 ? (
            <div className="space-y-4 animate-in slide-in-from-right duration-300">
              <div className="group">
                <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-1.5 ml-1">Nom Complet</label>
                <div className="relative">
                  <i className="fa-solid fa-user absolute left-4 top-1/2 -translate-y-1/2 text-gray-300"></i>
                  <input 
                    type="text" 
                    value={formData.name}
                    onChange={(e) => setFormData({...formData, name: e.target.value})}
                    className="w-full pl-12 pr-4 py-4 rounded-2xl bg-slate-50 border border-transparent focus:bg-white focus:border-emerald-500 outline-none transition-all shadow-sm"
                    placeholder="Moussa Koné"
                    required
                  />
                </div>
              </div>

              <div className="group">
                <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-1.5 ml-1">Email Professionnel</label>
                <div className="relative">
                  <i className="fa-solid fa-envelope absolute left-4 top-1/2 -translate-y-1/2 text-gray-300"></i>
                  <input 
                    type="email" 
                    value={formData.email}
                    onChange={(e) => setFormData({...formData, email: e.target.value})}
                    className="w-full pl-12 pr-4 py-4 rounded-2xl bg-slate-50 border border-transparent focus:bg-white focus:border-emerald-500 outline-none transition-all shadow-sm"
                    placeholder="moussa@agri.africa"
                    required
                  />
                </div>
              </div>

              <div className="group">
                <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-1.5 ml-1">Numéro de Téléphone</label>
                <div className="relative">
                  <i className="fa-solid fa-phone absolute left-4 top-1/2 -translate-y-1/2 text-gray-300"></i>
                  <input 
                    type="tel" 
                    value={formData.phone}
                    onChange={(e) => setFormData({...formData, phone: e.target.value})}
                    className="w-full pl-12 pr-4 py-4 rounded-2xl bg-slate-50 border border-transparent focus:bg-white focus:border-emerald-500 outline-none transition-all shadow-sm"
                    placeholder="+223 70 00 00 00"
                    required
                  />
                </div>
              </div>

              <button
                type="button"
                onClick={nextStep}
                disabled={!formData.name || !formData.email || !formData.phone}
                className="w-full bg-emerald-600 text-white py-4 rounded-2xl font-black text-lg shadow-xl shadow-emerald-900/20 disabled:opacity-30 flex items-center justify-center gap-2 mt-4 hover:bg-emerald-700 transition-colors"
              >
                Continuer <i className="fa-solid fa-arrow-right text-sm"></i>
              </button>
            </div>
          ) : (
            <div className="space-y-4 animate-in slide-in-from-right duration-300">
              <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-3 ml-1 text-center">Sélectionnez votre profil d'activité</label>
              <div className="grid grid-cols-1 gap-3">
                {roles.map((r) => (
                  <button
                    key={r}
                    type="button"
                    onClick={() => setFormData({...formData, role: r})}
                    className={`p-4 text-left rounded-2xl border-2 transition-all flex items-center justify-between group ${
                      formData.role === r 
                      ? 'bg-emerald-50 border-emerald-500 shadow-md ring-1 ring-emerald-500' 
                      : 'bg-white border-slate-100 hover:border-emerald-200'
                    }`}
                  >
                    <div className="flex items-center gap-3">
                      <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${formData.role === r ? 'bg-emerald-500 text-white' : 'bg-gray-50 text-gray-400'}`}>
                        <i className={`fa-solid ${r === 'ONG' ? 'fa-hand-holding-heart' : r === 'Agriculteur' ? 'fa-tractor' : r === 'Ingénieur Agronome' ? 'fa-graduat-cap' : 'fa-user'} text-sm`}></i>
                      </div>
                      <span className={`font-bold ${formData.role === r ? 'text-emerald-900' : 'text-gray-700'}`}>{r}</span>
                    </div>
                    {formData.role === r && <i className="fa-solid fa-circle-check text-emerald-500 animate-in zoom-in"></i>}
                  </button>
                ))}
              </div>

              <div className="flex gap-3 mt-6">
                <button type="button" onClick={prevStep} className="flex-1 bg-gray-100 text-gray-500 py-4 rounded-2xl font-bold">Retour</button>
                <button
                  type="submit"
                  disabled={!formData.role}
                  className="flex-[2] bg-emerald-600 text-white py-4 rounded-2xl font-black shadow-xl shadow-emerald-900/20 disabled:opacity-30"
                >
                  Finaliser l'Inscription
                </button>
              </div>
            </div>
          )}
        </form>
      </div>
    </div>
  );
};

export default Onboarding;

