export type StorageType = 'MySQL' | 'SQLite';

interface AppSettings {
  storageType: StorageType;
  language: 'FR' | 'EN';
  notifications: boolean;
  theme: 'light' | 'dark';
}

const DEFAULT_SETTINGS: AppSettings = {
  storageType: 'MySQL',
  language: 'FR',
  notifications: true,
  theme: 'light',
};

export const StorageService = {
  getSettings: (): AppSettings => {
    const saved = localStorage.getItem('agrovision_settings');
    return saved ? JSON.parse(saved) : DEFAULT_SETTINGS;
  },

  saveSettings: (settings: AppSettings) => {
    localStorage.setItem('agrovision_settings', JSON.stringify(settings));
    console.log(`[Storage] Configuration synchronisée avec la base de données ${settings.storageType}`);
  },

  // Simulation d'une requête vers MySQL ou SQLite
  syncData: async () => {
    const settings = StorageService.getSettings();
    return new Promise((resolve) => {
      setTimeout(() => {
        console.log(`[DB] Synchronisation terminée sur ${settings.storageType}`);
        resolve(true);
      }, 1500);
    });
  }
};

