const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [activeTab, setActiveTab] = useState<'scan' | 'community' | 'inbox' | 'ai' | 'settings'>('scan');
  const [isAppLoading, setIsAppLoading] = useState(true);

  useEffect(() => {
    // Simulation du chargement initial et synchro DB
    const init = async () => {
      await StorageService.syncData();
      setTimeout(() => setIsAppLoading(false), 3000);
    };
    init();
  }, []);

  const handleRegister = (data: { name: string, email: string, phone: string, role: UserRole }) => {
    const newUser: User = {
      id: Math.random().toString(36).substr(2, 9),
      ...data,
      avatar: `https://api.dicebear.com/7.x/avataaars/svg?seed=${data.email}`,
    };
    setUser(newUser);
    StorageService.syncData(); // On simule une synchro après inscription
  };

  if (isAppLoading) {
    return <LoadingScreen />;
  }

  if (!user) {
    return <Onboarding onComplete={handleRegister} />;
  }

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col max-w-md mx-auto relative shadow-2xl border-x border-gray-200 overflow-hidden">
      <Layout 
        user={user} 
        activeTab={activeTab} 
