import React, { useState, useRef } from 'react';
import { identifyPlant } from '../services/gemini';
import { PlantResult } from '../types';

const PlantScanner: React.FC = () => {
  const [loading, setLoading] = useState(false);
  const [image, setImage] = useState<string | null>(null);
  const [result, setResult] = useState<PlantResult | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const cameraInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64 = (reader.result as string).split(',')[1];
        setImage(reader.result as string);
        processImage(base64);
      };
      reader.readAsDataURL(file);
    }
  };

  const processImage = async (base64: string) => {
    setLoading(true);
    setResult(null);
    try {
      const res = await identifyPlant(base64);
      setResult(res);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const reset = () => {
    setImage(null);
    setResult(null);
  };

  return (
    <div className="p-4 space-y-6 animate-in fade-in duration-700">
      {!image ? (
        <div className="space-y-4">
          <div className="flex flex-col items-center justify-center h-[28rem] bg-white rounded-[2.5rem] border-2 border-dashed border-emerald-100 shadow-inner p-8 text-center relative overflow-hidden group">
