            <div className="w-24 h-24 bg-emerald-50 rounded-full flex items-center justify-center mb-6 relative shadow-lg group-hover:scale-110 transition-transform">
              <i className="fa-solid fa-qrcode text-4xl text-emerald-600 animate-pulse"></i>
            </div>

            <h2 className="text-2xl font-black text-gray-900 leading-tight">Diagnostic Intelligent</h2>
            <p className="text-gray-500 mt-3 text-sm max-w-[200px] leading-relaxed">Identifiez les herbes, plantes et maladies instantanément.</p>

            <div className="mt-10 grid grid-cols-1 w-full gap-3">
              <button 
                onClick={() => cameraInputRef.current?.click()}
                className="w-full bg-emerald-600 text-white px-6 py-4 rounded-2xl font-black shadow-xl shadow-emerald-900/20 hover:bg-emerald-700 transition-all flex items-center justify-center gap-3 active:scale-95"
              >
                <i className="fa-solid fa-camera"></i> Prendre en Photo
              </button>
              <button 
                onClick={() => fileInputRef.current?.click()}
                className="w-full bg-white text-emerald-600 border-2 border-emerald-50 px-6 py-4 rounded-2xl font-black shadow-sm hover:bg-emerald-50 transition-all flex items-center justify-center gap-3 active:scale-95"
              >
                <i className="fa-solid fa-images"></i> Importer une Image
              </button>
            </div>

            <input type="file" accept="image/*" capture="environment" ref={cameraInputRef} className="hidden" onChange={handleFileChange} />
            <input type="file" accept="image/*" ref={fileInputRef} className="hidden" onChange={handleFileChange} />
          </div>

          <div className="bg-amber-50 rounded-2xl p-4 flex gap-3 border border-amber-100">
            <i className="fa-solid fa-circle-info text-amber-500 mt-1"></i>
            <p className="text-[11px] text-amber-800 font-medium leading-relaxed">
              Conseil : Prenez la photo de près, avec un bon éclairage, pour une détection optimale des maladies par l'IA.
            </p>
          </div>
        </div>
      ) : (
        <div className="space-y-6 animate-in slide-in-from-bottom duration-500 pb-24">
          <div className="relative rounded-[2rem] overflow-hidden shadow-2xl border-4 border-white">
            <img src={image} alt="Cible" className="w-full h-72 object-cover" />
            <button 
              onClick={reset}
              className="absolute top-4 right-4 bg-white text-red-500 w-10 h-10 rounded-2xl flex items-center justify-center shadow-lg active:scale-90 transition-all"
