export type Language = 'FR' | 'EN';

import { GoogleGenAI, Type, GenerateContentResponse } from "@google/genai";
import { PlantResult } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

export const identifyPlant = async (base64Image: string): Promise<PlantResult | null> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: 'image/jpeg',
              data: base64Image,
            },
          },
          {
            text: `Analyse cette image de plante ou maladie agricole. 
            Si c'est une plante, identifie-la. Si c'est une maladie, décris-la.
            Retourne UNIQUEMENT un objet JSON valide suivant strictement cette structure :
            {
              "commonName": "Nom commun",
              "africanNames": ["nom1", "nom2"],
              "scientificName": "Nom scientifique",
              "isWeed": true/false,
              "benefits": ["avantage1"],
              "drawbacks": ["inconvenient1"],
              "healthImpact": {
                "advantages": ["bienfaits"],
                "disadvantages": ["risques"]
              },
              "eradicationMethod": "Méthode d'élimination ou soin",
              "description": "Description courte"
            }`
          }
        ]
      },
      config: {
        responseMimeType: "application/json",
      }
    });

    const text = response.text;
    if (!text) throw new Error("Réponse vide de l'IA");

    // Nettoyage potentiel du texte pour éviter les erreurs de parsing JSON
    const cleanJson = text.replace(/```json/g, "").replace(/```/g, "").trim();
    return JSON.parse(cleanJson) as PlantResult;
  } catch (error) {
    console.error("Gemini Error:", error);
    throw new Error(error instanceof Error ? error.message : "Erreur d'analyse IA");
  }
};

export const chatWithAI = async (message: string, history: { role: 'user' | 'model', parts: { text: string }[] }[]) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        { role: 'user', parts: [{ text: "Tu es un expert agronome africain. Réponds de manière concise, précise et encourageante." }] },
        ...history,
        { role: 'user', parts: [{ text: message }] }
      ]
    });
    return response.text || "Je n'ai pas pu formuler de réponse.";
  } catch (error) {
    console.error("AI Chat Error:", error);
    return "Erreur de communication avec l'assistant. Veuillez réessayer.";
  }
};

import React, { useState, useEffect, createContext, useContext } from 'react';
