import React, { useState, useRef } from 'react';
import { identifyPlant } from '../services/gemini';
import { PlantResult } from '../types';
import { useApp } from '../App';

const PlantScanner: React.FC = () => {
  const { showToast, language } = useApp();
  const [loading, setLoading] = useState(false);
  const [image, setImage] = useState<string | null>(null);
  const [result, setResult] = useState<PlantResult | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const cameraInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 10 * 1024 * 1024) {
        showToast("Image trop volumineuse (Max 10MB)", "error");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64 = (reader.result as string).split(',')[1];
        setImage(reader.result as string);
        processImage(base64);
      };
      reader.onerror = () => showToast("Erreur de lecture de fichier", "error");
      reader.readAsDataURL(file);
    }
  };

  const processImage = async (base64: string) => {
    setLoading(true);
    setResult(null);
    try {
      const res = await identifyPlant(base64);
      if (res) {
        setResult(res);
        showToast(language === 'FR' ? "Identification réussie !" : "Identification successful!", "success");
      } else {
        throw new Error("Résultat vide");
      }
    } catch (err) {
      console.error(err);
      showToast(language === 'FR' ? "IA : Échec de l'analyse. Image floue ?" : "AI: Analysis failed. Image blurry?", "error");
      setImage(null);
    } finally {
      setLoading(false);
    }
  };

  const reset = () => {
    setImage(null);
    setResult(null);
  };

  return (
    <div className="p-4 space-y-6 animate-in fade-in duration-700">
      {!image ? (
        <div className="space-y-4">
          <div className="flex flex-col items-center justify-center h-[28rem] bg-white rounded-[2.5rem] border-2 border-dashed border-emerald-100 shadow-inner p-8 text-center relative overflow-hidden group">
            <div className="absolute inset-0 bg-emerald-50/30 opacity-0 group-hover:opacity-100 transition-opacity"></div>

            <div className="w-24 h-24 bg-emerald-50 rounded-full flex items-center justify-center mb-6 relative shadow-lg group-hover:scale-110 transition-transform">
              <i className="fa-solid fa-leaf text-4xl text-emerald-600 animate-pulse"></i>
            </div>

            <h2 className="text-2xl font-black text-gray-900 leading-tight">
              {language === 'FR' ? 'Diagnostic Intelligent' : 'Smart Diagnostic'}
            </h2>
            <p className="text-gray-500 mt-3 text-sm max-w-[200px] leading-relaxed">
              {language === 'FR' ? 'Identifiez herbes, plantes et maladies.' : 'Identify weeds, plants and diseases.'}
            </p>

            <div className="mt-10 grid grid-cols-1 w-full gap-3">
              <button 
                onClick={() => cameraInputRef.current?.click()}
                className="w-full bg-emerald-600 text-white px-6 py-4 rounded-2xl font-black shadow-xl shadow-emerald-900/20 hover:bg-emerald-700 transition-all flex items-center justify-center gap-3 active:scale-95"
              >
                <i className="fa-solid fa-camera"></i> {language === 'FR' ? 'Caméra' : 'Camera'}
              </button>
              <button 
                onClick={() => fileInputRef.current?.click()}
                className="w-full bg-white text-emerald-600 border-2 border-emerald-50 px-6 py-4 rounded-2xl font-black shadow-sm hover:bg-emerald-50 transition-all flex items-center justify-center gap-3 active:scale-95"
              >
                <i className="fa-solid fa-images"></i> {language === 'FR' ? 'Galerie' : 'Gallery'}
              </button>
            </div>

            <input type="file" accept="image/*" capture="environment" ref={cameraInputRef} className="hidden" onChange={handleFileChange} />
            <input type="file" accept="image/*" ref={fileInputRef} className="hidden" onChange={handleFileChange} />
          </div>

          <div className="bg-amber-50 rounded-2xl p-4 flex gap-3 border border-amber-100">
            <i className="fa-solid fa-circle-info text-amber-500 mt-1"></i>
            <p className="text-[11px] text-amber-800 font-medium leading-relaxed italic">
              {language === 'FR' 
                ? 'Conseil : Rapprochez-vous de la zone infectée pour une détection optimale.' 
                : 'Tip: Get closer to the infected area for optimal detection.'}
            </p>
          </div>
        </div>
      ) : (
        <div className="space-y-6 animate-in slide-in-from-bottom duration-500 pb-24">
          <div className="relative rounded-[2.5rem] overflow-hidden shadow-2xl border-4 border-white">
            <img src={image} alt="Target" className="w-full h-80 object-cover" />
            {!loading && (
              <button 
                onClick={reset}
                className="absolute top-4 right-4 bg-white/90 backdrop-blur-sm text-red-500 w-10 h-10 rounded-2xl flex items-center justify-center shadow-lg active:scale-90 transition-all"
              >
                <i className="fa-solid fa-trash"></i>
              </button>
            )}
            {loading && (
              <div className="absolute inset-0 bg-emerald-900/60 backdrop-blur-md flex flex-col items-center justify-center text-white p-6 text-center">
                <div className="w-16 h-16 border-4 border-white/20 border-t-white rounded-full animate-spin mb-6"></div>
                <h3 className="font-black text-xl tracking-tighter uppercase">{language === 'FR' ? 'Analyse IA' : 'AI Analysis'}</h3>
