              </div>

              <Section title={language === 'FR' ? "Soin & Action" : "Care & Action"} icon="fa-kit-medical" color="bg-amber-500">
                <p className="text-sm text-gray-800 leading-relaxed font-semibold italic border-l-4 border-amber-300 pl-4 bg-amber-50/50 py-3 rounded-r-xl">
                  {result.eradicationMethod}
                </p>
              </Section>
            </div>
          )}
        </div>
      )}
    </div>
  );
