// Always use named parameter for apiKey and ensure it comes directly from process.env.API_KEY
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Identifie une plante ou une maladie à partir d'une image en utilisant Gemini.
 * Utilise responseSchema pour garantir une structure JSON valide.
 */
export const identifyPlant = async (base64Image: string): Promise<PlantResult | null> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: 'image/jpeg',
              data: base64Image,
            },
          },
          {
            text: `Analyse cette image de plante ou maladie agricole. 
            Si c'est une plante, identifie-la. Si c'est une maladie, décris-la.
            Retourne les informations demandées sous forme d'objet JSON.`
          }
        ]
      },
      config: {
        responseMimeType: "application/json",
        // Using responseSchema for robust and type-safe JSON extraction
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            commonName: { type: Type.STRING },
            africanNames: { type: Type.ARRAY, items: { type: Type.STRING } },
            scientificName: { type: Type.STRING },
            isWeed: { type: Type.BOOLEAN },
            benefits: { type: Type.ARRAY, items: { type: Type.STRING } },
            drawbacks: { type: Type.ARRAY, items: { type: Type.STRING } },
            healthImpact: {
              type: Type.OBJECT,
              properties: {
                advantages: { type: Type.ARRAY, items: { type: Type.STRING } },
                disadvantages: { type: Type.ARRAY, items: { type: Type.STRING } }
              },
              required: ["advantages", "disadvantages"]
            },
            eradicationMethod: { type: Type.STRING },
            description: { type: Type.STRING }
          },
          required: ["commonName", "africanNames", "scientificName", "isWeed", "benefits", "drawbacks", "healthImpact", "eradicationMethod", "description"]
        }
      }
    });

    // Use response.text property directly as per guidelines
    const text = response.text;
    if (!text) throw new Error("Réponse vide de l'IA");

    return JSON.parse(text) as PlantResult;
  } catch (error) {
    console.error("Gemini Error:", error);
    throw new Error(error instanceof Error ? error.message : "Erreur d'analyse IA");
  }
};

