/**
 * Exécute une requête avec un système de secours (Fallback).
 * Si le modèle Flash échoue ou atteint ses limites, on bascule sur Pro.
 */
async function executeWithFallback(params: Omit<GenerateContentParameters, 'model'>) {
  try {
    // Tentative avec Flash (Rapide et économique)
    return await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      ...params,
    });
  } catch (error) {
    console.warn("Flash model limit reached or error, switching to Pro...", error);
    // Basculement automatique sur Pro (Plus robuste)
    return await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      ...params,
    });
  }
}

