import React, { useState, useRef } from 'react';
import { identifyPlant } from '../services/gemini';
import { PlantResult } from '../types';
import { useApp } from '../App';

const MAX_SIZE_MB = 10;

const PlantScanner: React.FC = () => {
  const { showToast, language } = useApp();
  const [loading, setLoading] = useState(false);
  const [image, setImage] = useState<string | null>(null);
  const [result, setResult] = useState<PlantResult | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const cameraInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > MAX_SIZE_MB * 1024 * 1024) {
        showToast(`Image trop lourde ! Limite : ${MAX_SIZE_MB}Mo`, "error");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64 = (reader.result as string).split(',')[1];
        setImage(reader.result as string);
        processImage(base64);
      };
      reader.readAsDataURL(file);
    }
  };

  const processImage = async (base64: string) => {
    setLoading(true);
    setResult(null);
    try {
      const res = await identifyPlant(base64);
      if (res) {
        setResult(res);
        showToast(language === 'FR' ? "Analyse approfondie terminée !" : "In-depth analysis complete!", "success");
      }
    } catch (err) {
      showToast("L'IA est saturée ou l'image est illisible. Tentative de secours échouée.", "error");
      setImage(null);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="p-4 space-y-6 pb-28">
      {!image ? (
        <div className="space-y-4 animate-in fade-in duration-500">
          <div className="flex flex-col items-center justify-center h-[30rem] bg-white rounded-[3rem] border-4 border-dashed border-emerald-50 shadow-2xl p-8 text-center relative overflow-hidden group">
             <div className="absolute inset-0 bg-gradient-to-br from-emerald-50/50 to-transparent opacity-0 group-hover:opacity-100 transition-opacity"></div>

             <div className="w-28 h-28 bg-emerald-600 rounded-full flex items-center justify-center mb-8 shadow-xl shadow-emerald-200 animate-bounce">
                <i className="fa-solid fa-expand text-4xl text-white"></i>
             </div>

             <h2 className="text-3xl font-black text-gray-900 tracking-tight">Scanner Expert</h2>
             <p className="text-gray-500 mt-4 text-sm leading-relaxed max-w-[240px]">
               {language === 'FR' 
                ? 'Identifiez les maladies et mauvaises herbes avec notre IA multi-modale.' 
                : 'Identify diseases and weeds with our multi-modal AI.'}
             </p>

             <div className="mt-12 w-full space-y-3">
                <button 
                  onClick={() => cameraInputRef.current?.click()}
                  className="w-full bg-emerald-600 text-white py-5 rounded-2xl font-black shadow-lg active:scale-95 transition-all flex items-center justify-center gap-3"
                >
                  <i className="fa-solid fa-camera"></i> PRENDRE PHOTO
                </button>
                <button 
