import React, { useState, useRef, useEffect } from 'react';
import { identifyPlant } from '../services/gemini';
import { PlantResult, WeatherData } from '../types';
import { useApp } from '../App';

const MAX_SIZE_MB = 10;

const PlantScanner: React.FC = () => {
  const { showToast, language } = useApp();
  const [loading, setLoading] = useState(false);
  const [image, setImage] = useState<string | null>(null);
  const [result, setResult] = useState<PlantResult | null>(null);
  const [weather, setWeather] = useState<WeatherData | undefined>();
  const [coords, setCoords] = useState<{lat: number, lng: number} | undefined>();

  const fileInputRef = useRef<HTMLInputElement>(null);
  const cameraInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    // Récupérer la météo et la géo dès le montage
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition((pos) => {
        const c = { lat: pos.coords.latitude, lng: pos.coords.longitude };
        setCoords(c);
        // Simulation météo basée sur la position (remplace une API réelle type OpenWeather)
        setWeather({
          temp: 32,
          humidity: 65,
          condition: 'Ensoleillé',
          locationName: 'Région Locale'
        });
      });
    }
  }, []);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > MAX_SIZE_MB * 1024 * 1024) {
        showToast(`Image trop lourde ! Limite : ${MAX_SIZE_MB}Mo`, "error");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64 = (reader.result as string).split(',')[1];
        setImage(reader.result as string);
        processImage(base64);
      };
      reader.readAsDataURL(file);
    }
  };

  const processImage = async (base64: string) => {
    setLoading(true);
    setResult(null);
    try {
      const res = await identifyPlant(base64, weather, coords);
      if (res) {
        setResult(res);
        showToast("Diagnostic contextuel terminé !", "success");
      }
    } catch (err) {
      showToast("L'IA est saturée ou l'image est illisible.", "error");
      setImage(null);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="p-4 space-y-6 pb-28">
      {!image ? (
        <div className="space-y-4">
          <div className="flex flex-col items-center justify-center h-[30rem] bg-white rounded-[3rem] border-4 border-dashed border-emerald-50 shadow-2xl p-8 text-center relative overflow-hidden group">
             <div className="w-28 h-28 bg-emerald-600 rounded-full flex items-center justify-center mb-8 shadow-xl shadow-emerald-200">
                <i className="fa-solid fa-expand text-4xl text-white"></i>
             </div>
             <h2 className="text-3xl font-black text-gray-900 tracking-tight">Scanner Expert</h2>
             <p className="text-gray-500 mt-4 text-sm leading-relaxed max-w-[240px]">
               Analyse par image, climat et géolocalisation pour un diagnostic du sol précis.
             </p>

             <div className="mt-12 w-full space-y-3">
                <button onClick={() => cameraInputRef.current?.click()} className="w-full bg-emerald-600 text-white py-5 rounded-2xl font-black shadow-lg">PRENDRE PHOTO</button>
                <button onClick={() => fileInputRef.current?.click()} className="w-full bg-slate-100 text-slate-700 py-5 rounded-2xl font-black border border-slate-200">IMPORTER (MAX 10Mo)</button>
             </div>

             <input type="file" accept="image/*" capture="environment" ref={cameraInputRef} className="hidden" onChange={handleFileChange} />
             <input type="file" accept="image/*" ref={fileInputRef} className="hidden" onChange={handleFileChange} />
          </div>

          {weather && (
            <div className="bg-blue-50 p-4 rounded-2xl flex items-center justify-between border border-blue-100">
              <div className="flex items-center gap-3">
                <i className="fa-solid fa-cloud-sun text-blue-500 text-xl"></i>
                <div>
                  <p className="text-[10px] font-black text-blue-600 uppercase tracking-widest">Météo Locale</p>
                  <p className="text-xs font-bold text-blue-900">{weather.temp}°C • {weather.condition}</p>
                </div>
              </div>
              <p className="text-[10px] font-bold text-blue-400">{weather.locationName}</p>
            </div>
          )}
        </div>
      ) : (
        <div className="space-y-6">
          <div className="relative rounded-[2.5rem] overflow-hidden shadow-2xl border-8 border-white group">
            <img src={image} className="w-full h-80 object-cover" alt="Scan" />
            {loading && (
              <div className="absolute inset-0 bg-emerald-900/80 backdrop-blur-sm flex flex-col items-center justify-center text-white p-8">
                <div className="w-16 h-16 border-4 border-emerald-400/20 border-t-emerald-400 rounded-full animate-spin mb-4"></div>
                <h3 className="text-xl font-black uppercase tracking-widest italic">Fusion des Données...</h3>
                <p className="text-emerald-200/60 text-[10px] font-bold mt-2">ANALYSE DU SOL EN COURS</p>
              </div>
            )}
            {!loading && <button onClick={() => {setImage(null); setResult(null);}} className="absolute top-4 right-4 bg-white/90 text-red-500 p-3 rounded-2xl shadow-xl"><i className="fa-solid fa-xmark text-xl"></i></button>}
          </div>

          {result && (
            <div className="space-y-5 animate-in fade-in duration-1000">
              <div className="bg-white rounded-[2.5rem] p-8 shadow-xl border border-emerald-50">
                <div className="flex justify-between items-start mb-6">
                  <div>
                    <h2 className="text-4xl font-black text-slate-900 tracking-tight">{result.commonName}</h2>
                    <p className="text-emerald-600 font-bold italic mt-1">{result.scientificName}</p>
                  </div>
                  <div className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest ${result.isWeed || result.isDisease ? 'bg-red-50 text-red-500 border border-red-100' : 'bg-emerald-50 text-emerald-600 border border-emerald-100'}`}>
                    {result.isDisease ? 'Maladie' : result.isWeed ? 'Invasive' : 'Saine'}
                  </div>
                </div>

                <div className="flex gap-2 mb-6">
                   <div className="bg-orange-50 px-4 py-2 rounded-xl border border-orange-100 flex items-center gap-2">
                      <i className="fa-solid fa-mountain text-orange-500 text-xs"></i>
                      <span className="text-[10px] font-black text-orange-800 uppercase tracking-tighter">Sol: {result.soilType}</span>
                   </div>
                </div>

                <p className="text-slate-600 leading-relaxed text-sm font-medium">{result.description}</p>
              </div>

              <Section title="Éradication & Soins" icon="fa-shield-halved" color="bg-amber-500">
                <div className="space-y-3">
                  <MethodItem label="Biologique" text={result.eradicationMethod.biological} />
                  <MethodItem label="Mécanique" text={result.eradicationMethod.mechanical} />
                  <MethodItem label="Chimique" text={result.eradicationMethod.chemical} />
                </div>
              </Section>

              <Section title="Bienfaits & Santé" icon="fa-heart-pulse" color="bg-emerald-500">
                <p className="text-sm text-slate-700 leading-relaxed mb-4">{result.benefits}</p>
                <div className="grid grid-cols-2 gap-3">
                  <div className="bg-emerald-50 p-3 rounded-xl"><p className="text-[9px] font-black text-emerald-700 uppercase mb-1">Avantages</p><p className="text-[10px] text-slate-600">{result.healthImpact.advantages}</p></div>
                  <div className="bg-red-50 p-3 rounded-xl"><p className="text-[9px] font-black text-red-700 uppercase mb-1">Précautions</p><p className="text-[10px] text-slate-600">{result.healthImpact.disadvantages}</p></div>
                </div>
              </Section>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

const Section: React.FC<{title: string, icon: string, color: string, children: React.ReactNode}> = ({title, icon, color, children}) => (
  <div className="bg-white rounded-[2.5rem] p-8 shadow-xl border border-emerald-50">
